namespace ArchLucid.Persistence.IntegrationOutbox;internal static class IntegrationEventOutboxRepositoryCore{public const int MaxDequeueBatch=100;public const int MaxDeadLetterRows=500;public const int MaxErrorMessageLength=2048;public static int ClampDequeueBatch(int m)=>Math.Clamp(m,1,MaxDequeueBatch);public static int ClampDeadLetterRows(int m)=>Math.Clamp(m,1,MaxDeadLetterRows);public static int ClampDeadLetterSkip(int s)=>Math.Max(0,s);public static int DrainSortPriority(int? p)=>p??1;public static bool IsPendingDequeue(IntegrationEventOutboxEntry e,DateTime n){ArgumentNullException.ThrowIfNull(e);return e.DeadLetteredUtc is null&&(e.NextRetryUtc is null||e.NextRetryUtc<=n);}public static IEnumerable<IntegrationEventOutboxEntry> OrderPendingForDequeue(IEnumerable<IntegrationEventOutboxEntry> es,DateTime n){ArgumentNullException.ThrowIfNull(es);return es.Where(e=>IsPendingDequeue(e,n)).OrderBy(e=>DrainSortPriority(e.Priority)).ThenBy(e=>e.CreatedUtc);}public static string? NormalizeEventTypeFilter(string? e)=>string.IsNullOrWhiteSpace(e)?null:e.Trim();public static string? TruncateErrorMessage(string? m)=>m is null?null:m.Length<=MaxErrorMessageLength?m:m[..MaxErrorMessageLength];}